typedef enum {
    METER_PAGE_DASHBOARD = 0,
    METER_PAGE_GLOBAL_RESET = 1,
    METER_PAGE_STATUS = 2,
} meter_page_t;

esp_err_t board_lcd_init(void);
esp_err_t board_lcd_present(const char *frame,
                            uint32_t sequence,
                            bool has_frame,
                            bool receive_stale,
                            const char *last_error,
                            meter_page_t page,
                            uint64_t monotonic_ms,
                            uint64_t frame_accepted_ms,
